import heapq
import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = {}
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))

        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []

        adj[u].append((v, w))
        adj[v].append((u, w))

    start = int(next(iterator))

    visited = set()
    min_heap = []
    total_weight = 0
    nodes_connected = 0

    heapq.heappush(min_heap, (0, start))

    while min_heap and nodes_connected < n:
        weight, u = heapq.heappop(min_heap)

        if u in visited:
            continue

        visited.add(u)
        total_weight += weight
        nodes_connected += 1

        if u in adj:
            for v, w in adj[u]:
                if v not in visited:
                    heapq.heappush(min_heap, (w, v))

    print(total_weight)

if __name__ == "__main__":
    main()
